FACT_ONLY_STORY = set()  # every episode is a story (창작); the facts inside are cited in sources

for sid, (summary, facts, tags) in S.items():
    e = json.load(open(f"shorts/{sid}/edit.json"))
    names = []
    for s in e["sources"].values():
        n = s["creator"].split(" (")[0]
        if s["seconds"] and n not in names: names.append(n)
    src = facts + ([f"사진: Pexels({', '.join(names)})"] if names else []) + [OWN]
    title, _, _, _, _, pin = EP[sid]
    spec = {"title": title, "summary": summary, "fiction": True, "sources": src, "tags": tags, "pinned": pin}
    json.dump(spec, open(f"upload/specs/{sid}.json", "w"), ensure_ascii=False, indent=1)
print(len(S), "specs")
